from .pyro import PyroClient
from .local import LocalClient
from ..exceptions import UnknownClientError


class ClientBuilder:
    _lookup = {
        'PYRO': PyroClient,
        'LOCAL': LocalClient,
    }

    @staticmethod
    def __call__(client_type, *args, **kwargs):
        client_factory = ClientBuilder._lookup.get(client_type.upper())
        if client_factory is None:
            raise UnknownClientError(f"'{client_type}' - Supported clients: {str(list(ClientBuilder._lookup.keys()))}")
        client = client_factory(*args, **kwargs)
        client.setup()
        return client
